CREATE TABLE records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id text UNIQUE NOT NULL, timestamp timestamptz NOT NULL, temperature double precision, pressure double precision, voltage double precision, current double precision, flow_rate double precision, device_id text, source_type text, is_anomaly boolean DEFAULT false, anomaly_category text, created_at timestamptz DEFAULT now());
CREATE TABLE anomalies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id text NOT NULL, confidence double precision NOT NULL, severity text NOT NULL, category text, ae_score double precision, ae_error double precision, if_score double precision, symbolic_score double precision, fingerprint text, sea_state text, decision text, explanation text, violations jsonb DEFAULT '[]'::jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE fingerprints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fingerprint text UNIQUE NOT NULL, category text, severity text, signature jsonb NOT NULL, first_seen timestamptz DEFAULT now(), last_seen timestamptz DEFAULT now(), usage_count integer DEFAULT 1);
CREATE TABLE sea_states (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), state_id text UNIQUE NOT NULL, fingerprint text, anomaly_type text, severity text, recovery_strategy text, created_at timestamptz DEFAULT now(), usage_count integer DEFAULT 1, successful_recoveries integer DEFAULT 0);
CREATE TABLE sea_transitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_state text NOT NULL, to_state text NOT NULL, trigger text, created_at timestamptz DEFAULT now(), usage_count integer DEFAULT 1);
CREATE TABLE recovery_memory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fingerprint text NOT NULL, sea_state text NOT NULL, recovery_strategy text NOT NULL, outcome text NOT NULL, successful_uses integer DEFAULT 0, last_used timestamptz DEFAULT now());
CREATE TABLE experiments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, config jsonb NOT NULL, metrics jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE model_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_name text NOT NULL, precision_score double precision, recall_score double precision, f1_score double precision, false_positive_rate double precision, detection_time_ms double precision, created_at timestamptz DEFAULT now());
CREATE TABLE system_state (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz DEFAULT now());